import { useState } from 'react';
import { adminApi, pacientesApi } from '../../api';
import { Campo } from '../../components/Campo';
import { FormularioPaciente } from '../../components/FormularioPaciente';
import { Mensagem } from '../../components/Mensagem';
import { LinhasEsqueleto, Vazio } from '../../components/Vazio';
import { useCarregar } from '../../hooks/useCarregar';
import { useMensagem } from '../../hooks/useMensagem';
import { formatarDataHora } from '../../utils/formatadores';

export function PacientesPage() {
  const [busca, setBusca] = useState('');
  const { mensagem, sucesso, erro, limpar } = useMensagem();
  const { dados: pacientes, recarregar } = useCarregar(() => pacientesApi.listar(busca.trim()), [busca]);

  async function cadastrar(dados) {
    limpar();
    try {
      const paciente = await pacientesApi.criar(dados);
      sucesso(`${paciente.nome} já pode agendar consultas.`, 'Paciente cadastrado');
      recarregar();
      return true;
    } catch (e) {
      erro(e.message);
      return false;
    }
  }

  async function alternarAtivo(paciente) {
    limpar();
    try {
      await adminApi.definirAtivo(paciente.usuarioId, !paciente.ativo);
      sucesso(`${paciente.nome} foi ${paciente.ativo ? 'desativado' : 'reativado'}.`);
      recarregar();
    } catch (e) {
      erro(e.message);
    }
  }

  return (
    <>
      <div className="cartao">
        <h2>Novo paciente</h2>
        <p className="descricao">Campos com * são obrigatórios. O paciente usará o e-mail e a senha para entrar.</p>
        <FormularioPaciente prefixo="paciente" textoBotao="Cadastrar paciente" onEnviar={cadastrar}>
          <Mensagem id="paciente-mensagem" mensagem={mensagem} />
        </FormularioPaciente>
      </div>
      <div className="cartao">
        <h2>Pacientes cadastrados</h2>
        <p className="descricao">{pacientes ? `${pacientes.length} paciente(s).` : 'Carregando...'}</p>
        <Campo id="paciente-busca" rotulo="Buscar" type="search" placeholder="Nome, e-mail ou CPF" value={busca} onChange={(e) => setBusca(e.target.value)} />
        <div className="tabela-container">
          <table id="tabela-pacientes" className="responsiva">
            <thead><tr><th scope="col">Nome</th><th scope="col">E-mail</th><th scope="col">CPF</th><th scope="col">Nascimento</th><th scope="col">Situação</th><th scope="col"><span className="sr-only">Ações</span></th></tr></thead>
            <tbody>
              {!pacientes && <LinhasEsqueleto colunas={6} />}
              {pacientes?.length === 0 && <tr><td colSpan="6" className="vazio"><Vazio icone="usuarios">Nenhum paciente encontrado.</Vazio></td></tr>}
              {pacientes?.map((p) => (
                <tr key={p.id} data-usuario-id={p.usuarioId}>
                  <td data-label="Nome"><strong>{p.nome}</strong></td>
                  <td data-label="E-mail">{p.email}</td>
                  <td data-label="CPF">{p.cpf}</td>
                  <td data-label="Nascimento">{formatarDataHora(p.dataNascimento)}</td>
                  <td data-label="Situação"><span className={`status ${p.ativo ? 'status-CONFIRMADA' : 'status-CANCELADA'}`}>{p.ativo ? 'Ativo' : 'Inativo'}</span></td>
                  <td className="acoes"><button type="button" className="pequeno secundario" onClick={() => alternarAtivo(p)}>{p.ativo ? 'Desativar' : 'Ativar'}</button></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </>
  );
}

frontend/src/pages/recepcao/RelatorioPag.source:
import { useState } from 'react';
import { adminApi } from '../../api';
import { BotaoEnviar } from '../../components/BotaoEnviar';
import { Campo } from '../../components/Campo';
import { Mensagem } from '../../components/Mensagem';
import { StatusBadge } from '../../components/StatusBadge';
import { Vazio } from '../../components/Vazio';
import { useMensagem } from '../../hooks/useMensagem';
import { formatarMoeda } from '../../utils/formatadores';

export function RelatorioPage() {
  const [dataInicio, setDataInicio] = useState('');
  const [dataFim, setDataFim] = useState('');
  const [relatorio, setRelatorio] = useState(null);
  const [enviando, setEnviando] = useState(false);
  const { mensagem, erro, limpar } = useMensagem();

  async function gerar(evento) {
    evento.preventDefault();
    limpar();
    setEnviando(true);
    try {
      setRelatorio(await adminApi.resumo(dataInicio, dataFim));
    } catch (e) {
      setRelatorio(null);
      erro(e.message);
    } finally {
      setEnviando(false);
    }
  }

  const total = relatorio ? Object.values(relatorio.porStatus).reduce((a, b) => a + b, 0) : 0;

  return (
    <>
      <form className="cartao" onSubmit={gerar} noValidate>
        <h2>Período</h2>
        <div className="linha">
          <Campo id="relatorio-inicio" rotulo="De" type="date" value={dataInicio} onChange={(e) => setDataInicio(e.target.value)} />
          <Campo id="relatorio-fim" rotulo="Até" type="date" value={dataFim} onChange={(e) => setDataFim(e.target.value)} />
          <div className="campo"><BotaoEnviar id="relatorio-gerar" enviando={enviando} textoEnviando="Gerando...">Gerar relatório</BotaoEnviar></div>
        </div>
        <Mensagem id="relatorio-mensagem" mensagem={mensagem} />
        {!relatorio && !mensagem && <Vazio icone="grafico">Escolha um período para ver os indicadores.</Vazio>}
      </form>

      {relatorio && (
        <div id="relatorio-resultado">
          <div className="cartao">
            <h2>Consultas por status</h2>
            <div className="indicadores" id="relatorio-status">
              <div className="indicador destaque"><span className="rotulo">Total</span><strong>{total}</strong></div>
              {Object.entries(relatorio.porStatus).map(([s, n], i) => (
                <div key={s} className="indicador" style={{ animationDelay: `${(i + 1) * 60}ms` }}>
                  <span className="rotulo"><StatusBadge status={s} /></span>
                  <strong>{n}</strong>
                </div>
              ))}
            </div>
          </div>
          <div className="cartao">
            <h2>Faturamento</h2>
            <p className="descricao">Soma das consultas realizadas no período.</p>
            <p id="relatorio-faturamento" className="valor-destaque">{formatarMoeda(relatorio.faturamentoCentavos)}</p>
          </div>
          <div className="cartao">
            <h2>Faltas por médico</h2>
            <div className="tabela-container">
              <table id="relatorio-faltas" className="responsiva">
                <thead><tr><th scope="col">Médico</th><th scope="col">Faltas</th><th scope="col">Encerradas</th><th scope="col">Taxa de faltas</th></tr></thead>
                <tbody>
                  {relatorio.faltasPorMedico.length === 0 && <tr><td colSpan="4" className="vazio"><Vazio icone="grafico">Sem consultas no período.</Vazio></td></tr>}
                  {relatorio.faltasPorMedico.map((f) => (
                    <tr key={f.medicoId}>
                      <td data-label="Médico"><strong>{f.medicoNome}</strong></td>
                      <td data-label="Faltas">{f.faltas}</td>
                      <td data-label="Encerradas">{f.encerradas}</td>
                      <td data-label="Taxa de faltas">
                        <div style={{ display: 'flex', alignItems: 'center', gap: 10, justifyContent: 'inherit' }}>
                          <div className="barra-taxa" aria-hidden="true"><span style={{ width: `${Math.min(f.taxaFaltas, 100)}%` }} /></div>
                          {f.taxaFaltas}%
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

frontend/__testes__/unitario/formatadore.source:
import { describe, test, expect } from 'vitest';
import {
  formatarMoeda,
  formatarDataHora,
  hojeISO,
  NOMES_DIAS,
  STATUS_CONSULTA,
  estaAtiva,
} from '../../src/utils/formatadores';

describe('Formatadores Utilitários (formatadores.js)', () => {
  // --- formatarMoeda (RN22, RNF06) ---
  /**
   * @caso CT-UNI-071
   * @nivel unitario
   * @atributo usabilidade
   * @subatributo reconhecibilidade
   * @requisito RN22, RNF06
   * @objetivo Formatar valor em centavos para moeda brasileira BRL
   * @resultadoEsperado Retornar string no formato de moeda contendo '150,00'
   */
  test('deve formatar centavos para moeda Real (BRL)', () => {
    const formatado = formatarMoeda(15000);
    // substitui possíveis non-breaking space (char 160) por espaço simples
    const normalizado = formatado.replace(/\u00a0/g, ' ');
    expect(normalizado).toContain('150,00');
    expect(normalizado).toContain('R$');
  });

  /**
   * @caso CT-UNI-072
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN24, RNF06
   * @objetivo Formatar valor zero centavos
   * @resultadoEsperado Retornar representação de R$ 0,00
   */
  test('deve formatar zero centavos como R$ 0,00', () => {
    const formatado = formatarMoeda(0).replace(/\u00a0/g, ' ');
    expect(formatado).toContain('0,00');
  });

  // --- formatarDataHora (RNF06) ---
  /**
   * @caso CT-UNI-073
   * @nivel unitario
   * @atributo usabilidade
   * @subatributo reconhecibilidade
   * @requisito RNF06
   * @objetivo Converter data no formato ISO AAAA-MM-DD para DD/MM/AAAA
   * @resultadoEsperado Formato brasileiro de data
   */
  test('deve formatar data simples sem hora para formato DD/MM/AAAA', () => {
    expect(formatarDataHora('2026-10-19')).toBe('19/10/2026');
  });

  /**
   * @caso CT-UNI-074
   * @nivel unitario
   * @atributo usabilidade
   * @subatributo reconhecibilidade
   * @requisito RNF06
   * @objetivo Converter data e hora AAAA-MM-DD HH:mm para DD/MM/AAAA HH:mm
   * @resultadoEsperado Formato brasileiro completo com horário
   */
  test('deve formatar data com hora para DD/MM/AAAA HH:mm', () => {
    expect(formatarDataHora('2026-10-19 08:30')).toBe('19/10/2026 08:30');
  });

  /**
   * @caso CT-UNI-075
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RNF06
   * @objetivo Retornar string vazia quando entrada for nula ou indefinida
   * @resultadoEsperado formatarDataHora retorna ''
   */
  test('deve lidar com valor vazio de data graciosamente', () => {
    expect(formatarDataHora('')).toBe('');
    expect(formatarDataHora(null)).toBe('');
    expect(formatarDataHora(undefined)).toBe('');
  });

  // --- hojeISO (RNF06) ---
  /**
   * @caso CT-UNI-076
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RNF06
   * @objetivo Gerar string da data atual no padrão AAAA-MM-DD
   * @resultadoEsperado Formato regex /^\d{4}-\d{2}-\d{2}$/
   */
  test('deve retornar data no formato ISO AAAA-MM-DD', () => {
    const hoje = hojeISO();
    expect(hoje).toMatch(/^\d{4}-\d{2}-\d{2}$/);
  });

  // --- NOMES_DIAS e STATUS_CONSULTA ---
  /**
   * @caso CT-UNI-077
   * @nivel unitario
   * @atributo manutenibilidade
   * @subatributo modularidade
   * @requisito RNF07
   * @objetivo Validar array de dias e lista de status
   * @resultadoEsperado NOMES_DIAS possui 7 itens começando em Domingo e STATUS_CONSULTA tem os 5 status
   */
  test('deve expor constantes de dias e status corretas', () => {
    expect(NOMES_DIAS).toHaveLength(7);
    expect(NOMES_DIAS[0]).toBe('Domingo');
    expect(NOMES_DIAS[6]).toBe('Sábado');
    expect(STATUS_CONSULTA).toEqual(['AGENDADA', 'CONFIRMADA', 'REALIZADA', 'FALTA', 'CANCELADA']);
  });

  // --- estaAtiva (RF09, RN25) ---
  /**
   * @caso CT-UNI-078
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RF09
   * @objetivo Identificar se o objeto de consulta está com status ativo
   * @resultadoEsperado estaAtiva retorna true para AGENDADA e CONFIRMADA, false para os demais
   */
  test('deve verificar se consulta é ativa no frontend', () => {
    expect(estaAtiva({ status: 'AGENDADA' })).toBe(true);
    expect(estaAtiva({ status: 'CONFIRMADA' })).toBe(true);
    expect(estaAtiva({ status: 'REALIZADA' })).toBe(false);
    expect(estaAtiva({ status: 'CANCELADA' })).toBe(false);
    expect(estaAtiva({ status: 'FALTA' })).toBe(false);
  });
});

